import { expect, test, uniqueName } from "../../fixtures";

test.describe("Manage vendors", () => {
  test(
    "Vendors from another tenant are invisible",
    { tag: "@VEN-07" },
    async ({ apiAs }) => {
      // Arrange: a vendor exists in the Globex Procurement tenant
      const globex = await apiAs("otherTenant");
      const created = await globex.post("/api/vendors", {
        data: {
          name: uniqueName("Globex Vendor"),
          category: "software",
          contact_email: "billing@globex-vendor.test",
        },
      });
      expect(created.status()).toBe(201);
      const globexVendor = await created.json();

      // Act: a Northwind member requests that vendor by id
      const member = await apiAs("member");
      const response = await member.get(`/api/vendors/${globexVendor.id}`);

      // Assert
      expect(response.status()).toBe(404);
      expect((await response.json()).error.code).toBe("vendor_not_found");
    },
  );
});
